def parse_rows(lines):
    errors = []
    totals = {}
    for number, line in enumerate(lines, start=1):
        try:
            name, qty = line.split(",")
            totals[name] = int(qty)
        except ValueError as exc:
            exc.add_note(f"line {number}: {line!r}")
            errors.append(exc)
    if errors:
        raise ExceptionGroup("bad rows", errors)
    return totals

try:
    parse_rows(["a,1", "b,x", "c,2", "d,"])
except ExceptionGroup as eg:
    for e in eg.exceptions:
        print(e, e.__notes__)
